import numpy as np

class RippleBasin:
    def __init__(self, dim=5):
        self.dim = dim
        self.centers = np.random.uniform(-4, 4, size=(10, dim))  # Random centers for local minima
        self.weights = np.random.uniform(0.5, 1.5, size=10)     # Random weights for each center

    def f(self, x):
        # Global basin term (quadratic)
        global_term = np.sum(x**2)

        # Local basin terms (sinusoidal with polynomial modulation)
        local_terms = np.zeros(10)
        for i in range(10):
            dist = np.linalg.norm(x - self.centers[i])
            local_terms[i] = self.weights[i] * np.sin(5 * dist) * (1 + 0.1 * dist**2)

        # Combine terms to create homogeneous basins
        return global_term + 0.5 * np.sum(local_terms)
